'use strict';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let wizardStep=0, drawingBackground=null, drawingImage=null, formDirty=false, resultsDirty=false, uploadBusy=false, resultTab='images', submitBusy=false, pendingRequestId=null;
const imageCache=new Map();
function statusMessage(id,text,error=false){const el=$(id);if(el){el.textContent=text;el.classList.toggle('error-inline',error);}}
function humanBytes(n){return (n/1000000).toFixed(2)+' MB';}
function uid(){return 'm_'+crypto.randomUUID().replaceAll('-','');}
function rawRequest(){return requests.find(r=>r.id===selectedReqId);}

// Image processing is shared by uploads, pasted screenshots and the drawing background.
async function loadImage(src){if(imageCache.has(src))return imageCache.get(src);const img=new Image();if(src.startsWith('https:'))img.crossOrigin='anonymous';img.src=src;await img.decode();imageCache.set(src,img);return img;}
async function optimizeImage(file,maxEdge=1800,target=240000){
  if(!/^image\/(png|jpeg|webp|gif|bmp)$/.test(file.type))throw Error('Use PNG, JPG, WebP, GIF or BMP. Export a CAD view as a picture to mark the cut.');
  if(file.size>60000000)throw Error('This image exceeds 60 MB. Export a smaller view first.');
  const url=URL.createObjectURL(file);let image;
  try{image=new Image();image.src=url;await image.decode();if(image.naturalWidth*image.naturalHeight>80000000)throw Error('Image exceeds 80 megapixels. Export a smaller view.');
    const cv=document.createElement('canvas'),scale=Math.min(1,maxEdge/Math.max(image.naturalWidth,image.naturalHeight));cv.width=Math.max(1,Math.round(image.naturalWidth*scale));cv.height=Math.max(1,Math.round(image.naturalHeight*scale));let ctx=cv.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,cv.width,cv.height);ctx.drawImage(image,0,0,cv.width,cv.height);
    let data=cv.toDataURL('image/jpeg',.88),quality=.88;while(data.length>target&&quality>.43){quality-=.09;data=cv.toDataURL('image/jpeg',quality);}while(data.length>target&&cv.width>600){const tmp=document.createElement('canvas');tmp.width=Math.round(cv.width*.83);tmp.height=Math.round(cv.height*.83);tmp.getContext('2d').drawImage(cv,0,0,tmp.width,tmp.height);cv.width=tmp.width;cv.height=tmp.height;cv.getContext('2d').drawImage(tmp,0,0);data=cv.toDataURL('image/jpeg',.72);}
    return {src:data,name:file.name||'Pasted screenshot',width:cv.width,height:cv.height,originalBytes:file.size};
  }finally{URL.revokeObjectURL(url);}
}

const originalDashboard=renderDashboard;
renderDashboard=function(){
  const count=s=>requests.filter(r=>s.includes(r.status)).length;
  $('view-dashboard').innerHTML=`<section class="hero"><div><div class="eyebrow">NVIDIA · Process engineering</div><h1>From cut plan<br>to clear findings.</h1><p>One workspace for cross-section requests, annotated sample drawings, microscopy images, and measured results.</p><div class="actions"><button class="primary" onclick="showView('new')">Create X-section request</button><button onclick="showView('requests')">Browse requests</button></div></div><div class="hero-art">${makeDiagramSVG('standard',520,260)}<small>Define the region. Mark the cut. Capture the evidence.</small></div></section><div class="metrics">${[['To prepare',['open']],['In the lab',['progress']],['To review',['review']],['Completed',['done','closed']]].map(([label,s])=>`<button onclick="filterStatus='${s[0]}';showView('requests')"><span class="muted">${label}</span><strong>${count(s)}</strong></button>`).join('')}</div><div class="section-head"><h2>Recent requests</h2><button class="ghost" onclick="showView('requests')">View all</button></div>${requests.length?requests.slice(0,8).map(r=>`<button class="request-row" onclick="openDetail('${esc(r.id)}')"><div><small>${esc(r.id)} · ${esc(r.sampleId)}</small><strong>${esc(r.product)} · ${esc(r.objective)}</strong><small>${esc(r.requesterName||userName(r.requester))} · ${esc(fmtDay(r.created))}</small></div><div>${pillHTML(r.status)}<br><small>${(r.messages||[]).reduce((n,m)=>n+(m.images?.length||0),0)} images</small></div></button>`).join(''):`<div class="empty-state"><h3>Your first cross-section starts here</h3><p>Add a sample, upload a picture or choose a drawing, and show the lab exactly where to cut.</p><button class="primary" onclick="showView('new')">Create first request</button></div>`}`;
};

// Reuse the existing engineering drawing tools, while progressively revealing the request form.
const originalNew=renderNew;
renderNew=function(){
  originalNew();wizardStep=0;drawingBackground=null;drawingImage=null;formDirty=false;pendingRequestId=null;
  const view=$('view-new');view.classList.add('wizard');const card=view.querySelector('.card'),nodes=[...card.childNodes];
  view.firstElementChild.className='wizard-header';view.firstElementChild.removeAttribute('style');view.firstElementChild.innerHTML='<div><div class="eyebrow">New X-section request</div><h1>Show us where to cut.</h1><p class="muted">Start with your sample. Add a picture or a drawing. Tell the lab what to investigate.</p></div><button class="ghost" onclick="showView(\'dashboard\')">Back to workspace</button>';
  const steps=document.createElement('nav');steps.className='steps';steps.setAttribute('aria-label','Request steps');steps.innerHTML=['Sample & objective','Picture & cut plan','Review & submit'].map((s,i)=>`<button type="button" id="step-button-${i}" onclick="goStep(${i})"><span>${i+1}</span>${s}</button>`).join('');view.insertBefore(steps,card);
  card.innerHTML='';const panels=[0,1,2].map(i=>{const el=document.createElement('section');el.className='step-panel';el.id='step-panel-'+i;card.appendChild(el);return el;});let group=0;
  for(const n of nodes){if(n.nodeType===1&&n.classList.contains('sep')){const t=n.textContent;if(t.includes('Diagram type'))group=1;else if(t.includes('Analysis requirements'))group=0;else if(t.includes('Assign and notify'))group=2;}if(n.nodeType===1&&(n.id==='form-err'||n.querySelector('button[onclick="submitRequest()"]')))continue;panels[group].appendChild(n);}
  panels[2].insertAdjacentHTML('afterbegin','<h2 style="margin-bottom:16px">Ready for the lab?</h2><div id="request-review" class="review-box"></div>');
  const source=document.createElement('div');source.innerHTML=`<h2>Start with a view of your sample</h2><p class="muted" style="margin:8px 0 16px">Use a module photo, CAD screenshot, or one of the built-in package drawings.</p><div class="source-options"><button class="primary" onclick="$('drawing-upload').click()">Upload picture / screenshot</button><button onclick="$('template-picker').open=!$('template-picker').open">Choose a drawing</button><button onclick="blankDrawing()">Draw from scratch</button></div><div class="drop-zone" id="drawing-drop" tabindex="0"><strong>Drop a picture here, or paste a screenshot</strong><p>PNG, JPG, WebP, GIF or BMP · Ctrl+V / ⌘V while on this step</p><input id="drawing-upload" type="file" accept="image/png,image/jpeg,image/webp,image/gif,image/bmp" hidden onchange="useDrawingFile(this.files[0])"><div id="drawing-status" class="upload-status" role="status"></div></div><div class="drawing-help">Mark the cut line, add an arrow or label, and identify the lid, die, substrate, or region of interest. Drawings are schematic; dimensions you type are labels.</div>`;
  panels[1].prepend(source);const templateTitle=[...panels[1].querySelectorAll('.sep')].find(n=>n.textContent.includes('Diagram type'));const templateDiv=templateTitle.nextElementSibling;const details=document.createElement('details');details.id='template-picker';details.className='advanced-tools';details.innerHTML='<summary>Built-in drawings · package, lid, TIM, interconnect & optical modules</summary>';templateTitle.before(details);details.append(templateDiv);templateTitle.remove();
  document.querySelectorAll('.diagram-option').forEach(el=>{const id=el.id.slice(5);el.dataset.grp=DIAGRAM_GROUPS.find(g=>g.items.some(d=>d.id===id))?.group||'';el.tabIndex=0;el.setAttribute('role','button');el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectDiagram(id);}});});
  const toolbar=$('xs-toolbar');for(let i=0;i<2;i++){const row=toolbar.nextElementSibling;if(!row||row.tagName==='CANVAS')break;if(i===0){const d=document.createElement('details');d.className='advanced-tools';d.innerHTML='<summary>Color, line style & fill</summary>';row.before(d);d.append(row);}else break;}
  card.insertAdjacentHTML('beforeend','<div id="form-err" class="error-inline" role="alert" style="display:none"></div><div class="draft-note" id="draft-status">Your request stays in this tab until submitted.</div><div class="wizard-nav"><button id="wizard-back" onclick="goStep(wizardStep-1)">Previous</button><div class="actions"><button class="ghost" onclick="clearNewForm()">Clear form</button><button id="wizard-next" class="primary" onclick="goStep(wizardStep+1)">Continue</button><button id="wizard-submit" class="primary" onclick="submitRequest()" hidden>Submit request</button></div></div>');
  // Real labels and focus targets for the reused form controls.
  view.querySelectorAll('.form-group').forEach(g=>{const input=g.querySelector('input,select,textarea'),label=g.querySelector('.form-label');if(input&&label){if(!input.id)input.id='field-'+uid();const native=document.createElement('label');native.className=label.className;native.innerHTML=label.innerHTML;native.htmlFor=input.id;label.replaceWith(native);}});
  $('f-background').placeholder='What do you want to learn? Include the suspected defect, relevant process history, target values, and acceptance criteria.';
  $('f-product').insertAdjacentHTML('afterbegin','<option value="" selected>Select product / platform</option>');
  $('f-product').insertAdjacentHTML('beforeend','<option>GPU / ASIC package</option><option>HBM package</option><option>Custom module</option>');
  panels[0].insertAdjacentHTML('beforeend','<div class="form-group" style="margin-top:18px"><label class="form-label" for="f-product-custom">Product / module name (optional)</label><input id="f-product-custom" placeholder="Enter the exact platform or module name"></div>');
  addDropZone($('drawing-drop'),files=>useDrawingFile(files[0]));
  view.addEventListener('input',()=>{formDirty=true;statusMessage('draft-status','Draft changed · saved on this device automatically.');scheduleDraft();});
  goStep(0,false);offerDraft();
};

const originalBuildToolbar=buildToolbar;
buildToolbar=function(){originalBuildToolbar();const tb=$('xs-toolbar'),all=[...tb.querySelectorAll('button')],basic=new Set(['select','cutline','cross','arrow','text','rect','dimline']);tb.innerHTML='';const extra=document.createElement('details');extra.className='advanced-tools';extra.innerHTML='<summary>More drawing tools</summary><div class="actions"></div>';all.forEach(b=>{const tool=b.id.replace('xtool-','');if(basic.has(tool)){b.textContent=({'select':'Move','cutline':'Cut line','cross':'Cut point','arrow':'Arrow','text':'Text','rect':'Box','dimline':'Dimension'})[tool];tb.append(b);}else extra.lastElementChild.append(b);});tb.append(extra);};
const originalDrawShape=drawShape;
drawShape=function(ctx,s,preview=false){if(s.type==='image'){const img=imageCache.get(s.src);if(img)ctx.drawImage(img,s.x,s.y,s.x2-s.x,s.y2-s.y);return;}originalDrawShape(ctx,s,preview);};
async function setDrawingSource(src,label){
  const img=await loadImage(src);canvasHistory.push(JSON.stringify(canvasShapes));const scale=Math.min(680/img.naturalWidth,360/img.naturalHeight);canvasShapes=[{type:'image',src,x:40,y:40,x2:40+img.naturalWidth*scale,y2:40+img.naturalHeight*scale},...canvasShapes.filter(s=>s.type!=='image')];drawingBackground=src;drawingImage=img;canvasSelected=null;canvasRedraw();setTool('cutline');statusMessage('drawing-status',label+' loaded. Draw the cut line over the picture.');formDirty=true;scheduleDraft();
}
selectDiagram=async function(id){selectedDiagram=id;try{const svg=makeDiagramSVG(id,900,540),src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);const img=new Image();img.src=src;await img.decode();const cv=document.createElement('canvas');cv.width=900;cv.height=540;const ctx=cv.getContext('2d');ctx.fillStyle='#1a1a1a';ctx.fillRect(0,0,900,540);ctx.drawImage(img,0,0,900,540);await setDrawingSource(cv.toDataURL('image/png'),DIAGRAMS.find(d=>d.id===id)?.label||id);$('template-picker').open=false;document.querySelectorAll('.diagram-option').forEach(el=>el.classList.toggle('selected',el.id==='dopt-'+id));}catch(e){statusMessage('drawing-status','Drawing could not be loaded: '+e.message,true);}};
async function useDrawingFile(file){if(!file)return;try{statusMessage('drawing-status','Preparing picture…');const image=await optimizeImage(file,1800,600000);selectedDiagram='custom';await setDrawingSource(image.src,image.name);}catch(e){statusMessage('drawing-status',e.message,true);}}
function blankDrawing(){canvasHistory.push(JSON.stringify(canvasShapes));canvasShapes=[];drawingBackground=null;canvasRedraw();setTool('rect');statusMessage('drawing-status','Blank drawing. Add parts, labels and a cut line.');formDirty=true;scheduleDraft();}
function addDropZone(el,handler){el.addEventListener('dragover',e=>{e.preventDefault();el.classList.add('dragover');});el.addEventListener('dragleave',()=>el.classList.remove('dragover'));el.addEventListener('drop',e=>{e.preventDefault();el.classList.remove('dragover');handler([...e.dataTransfer.files]);});el.addEventListener('keydown',e=>{if(e.key==='Enter')el.querySelector('input[type=file]')?.click();});}
function goStep(step,validate=true){
  if(step<0||step>2)return;if(validate&&step>wizardStep){let missing=null;if(!$('f-sampleId').value.trim())missing=$('f-sampleId');else if(!$('f-product').value&&!$('f-product-custom').value.trim())missing=$('f-product');if(missing){wizardStep=0;showStep();statusMessage('form-err','Enter the sample ID and select or type the product name.',true);$('form-err').style.display='block';missing.focus();return;}if(step===2&&!$('f-cutLocation').value.trim()){statusMessage('form-err','Describe the cut location so the lab can identify it.',true);$('form-err').style.display='block';$('f-cutLocation').focus();return;}}
  wizardStep=step;showStep();$('form-err').style.display='none';if(step===2)$('request-review').innerHTML=`<h3>${esc($('f-sampleId').value)} · ${esc($('f-product-custom').value||$('f-product').value)}</h3><p class="muted" style="margin:10px 0">${esc($('f-objective').value)} · ${esc($('f-priority').value)}</p><p>${esc($('f-cutLocation').value)}</p><p class="muted" style="margin-top:8px">${$('f-numCuts').value} cut(s) · ${esc($('f-cutPlane').value)} · ${canvasShapes.length?'Drawing attached':'Text-only cut plan'}</p>`;
}
function showStep(){for(let i=0;i<3;i++){const panel=$('step-panel-'+i);panel.hidden=i!==wizardStep;$('step-button-'+i).classList.toggle('active',i===wizardStep);$('step-button-'+i).setAttribute('aria-current',i===wizardStep?'step':'false');}$('wizard-back').hidden=wizardStep===0;$('wizard-next').hidden=wizardStep===2;$('wizard-submit').hidden=wizardStep!==2;}

// A local IndexedDB draft survives a tab reload without putting images in localStorage.
let draftTimer,dbPromise;
function draftDB(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('xsection-workspace',1);r.onupgradeneeded=()=>r.result.createObjectStore('drafts');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});return dbPromise;}
async function draftOp(mode,value){const db=await draftDB();return new Promise((resolve,reject)=>{const tx=db.transaction('drafts',mode==='get'?'readonly':'readwrite'),s=tx.objectStore('drafts'),r=mode==='get'?s.get('new-request'):mode==='delete'?s.delete('new-request'):s.put(value,'new-request');tx.oncomplete=()=>resolve(r.result);tx.onerror=()=>reject(tx.error);});}
function captureDraft(){return {fields:Object.fromEntries([...$('view-new').querySelectorAll('[id^="f-"]')].map(el=>[el.id,el.value])),shapes:canvasShapes,diagram:selectedDiagram,width:_cvs?.width,height:_cvs?.height,date:new Date().toISOString()};}
function scheduleDraft(){clearTimeout(draftTimer);draftTimer=setTimeout(()=>{if(currentView==='new'&&formDirty)draftOp('put',captureDraft()).then(()=>statusMessage('draft-status','Draft saved on this device · not submitted.')).catch(()=>statusMessage('draft-status','Device draft unavailable. Keep this tab open.'));},700);}
async function offerDraft(){try{const draft=await draftOp('get');if(draft&&currentView==='new'){const el=$('draft-status');el.innerHTML='A saved draft is available on this device. <button class="small" id="restore-draft">Restore draft</button>';const button=$('restore-draft');button.onclick=async()=>{for(const [id,v]of Object.entries(draft.fields))if($(id))$(id).value=v;await Promise.all(draft.shapes.filter(s=>s.type==='image').map(s=>loadImage(s.src)));canvasShapes=draft.shapes;selectedDiagram=draft.diagram;if(draft.width){_cvs.width=draft.width;_cvs.height=draft.height;}canvasRedraw();formDirty=true;statusMessage('draft-status','Draft restored. Continue editing or submit.');};}}catch{}}
clearNewForm=async function(){if(formDirty&&!confirm('Clear this draft and its drawing?'))return;clearTimeout(draftTimer);await draftOp('delete').catch(()=>{});formDirty=false;renderNew();};
submitRequest=async function(){
  if(submitBusy||uploadBusy)return;goStep(2);if(wizardStep!==2)return;
  const sampleId=$('f-sampleId').value.trim(),location=$('f-cutLocation').value.trim();if(!sampleId||!location)return;
  if(!sharedReady){statusMessage('form-err','Shared saving is not connected. Your device draft is retained. Retry the connection before submitting.',true);$('form-err').style.display='block';return;}
  submitBusy=true;$('wizard-submit').disabled=true;try{const now=new Date().toISOString(),id=pendingRequestId||genId();pendingRequestId=id;const product=$('f-product-custom').value.trim()||$('f-product').value;const req={id,status:'open',sampleId,product,lot:$('f-lot').value.trim(),stage:$('f-stage').value,cutPlane:$('f-cutPlane').value,numCuts:Number($('f-numCuts').value),cutLocation:location,objective:$('f-objective').value,mag:$('f-mag').value,measurement:$('f-measurement').value,priority:$('f-priority').value,background:$('f-background').value.trim(),diagramType:selectedDiagram,canvasDrawing:canvasShapes.length?canvasGetDataURL():null,diagramScene:{shapes:canvasShapes,width:_cvs.width,height:_cvs.height},requester:currentUser.id,requesterName:currentUser.name,analyst:$('f-analyst').value||null,created:now,messages:[]};
    XSectionStore.valid(req);const existing=requests.findIndex(r=>r.id===id);if(existing<0)requests.unshift(req);else requests[existing]=req;if(!await saveData())return;clearTimeout(draftTimer);await draftOp('delete').catch(()=>{});formDirty=false;pendingRequestId=null;openDetail(id);showToast('Request submitted to the lab.');
  }catch(e){statusMessage('form-err',e.message,true);$('form-err').style.display='block';}finally{submitBusy=false;if($('wizard-submit'))$('wizard-submit').disabled=false;}
};

function storageMarkup(r){const cap=XSCore.capacity(r);return `<div class="storage-meter" role="meter" aria-label="Shared request capacity" aria-valuenow="${Math.round(cap.percent)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${cap.percent}%"></span></div><div class="storage-copy">${humanBytes(cap.used)} / 8 MB shared record capacity · pictures are optimized before saving.</div>`;}
function requestImages(r){return (r.messages||[]).flatMap(m=>(m.images||[]).map((src,i)=>({src,key:m.id+'_'+i,name:m.imageNames?.[i]||'Image '+(i+1),type:m.kind||'analysis',date:m.ts,originalURL:m.imageMeta?.[i]?.originalURL})));}
const originalDetail=renderDetail;
renderDetail=function(){
  originalDetail();const r=rawRequest();if(!r)return;const view=$('view-detail'),target=document.createElement('section');target.className='card results-workspace';target.id='results-workspace';const images=requestImages(r),measurements=Object.values(r.resultMeasurements||{});const summary=r.results||{};
  target.innerHTML=`<div class="section-head" style="margin:0"><div><div class="eyebrow" style="margin-bottom:6px">Analysis workspace</div><h2>Images, measurements & findings</h2></div><button onclick="printReport()">Print / save PDF</button></div><p class="muted" style="margin-top:10px">Keep the sample evidence and the engineering decision together.</p><nav class="results-tabs" aria-label="Analysis sections">${[['images','Images · '+images.length],['measurements','Measurements · '+measurements.length],['summary','Summary & conclusion']].map(([id,label])=>`<button id="result-tab-${id}" onclick="selectResultTab('${id}')">${label}</button>`).join('')}</nav>
  <div id="result-panel-images" class="results-panel"><h3 class="report-heading">X-section images</h3><div class="drop-zone" id="results-drop" tabindex="0"><strong>Add cross-section photos or microscope screenshots</strong><p>Upload multiple images, drop them here, or paste a screenshot. Add captions and measure from each image.</p><button class="primary" onclick="$('result-upload').click()">Add X-section images</button><input type="file" id="result-upload" accept="image/png,image/jpeg,image/webp,image/gif,image/bmp" multiple hidden onchange="uploadResultImages([...this.files])"><div id="result-upload-status" class="upload-status" role="status"></div></div>${storageMarkup(r)}<div class="gallery">${images.map(img=>`<article class="image-card"><img src="${esc(img.src)}" alt="${esc(r.imageAnnotations?.[img.key]?.caption||img.name)}" loading="lazy"><div><p>${esc(r.imageAnnotations?.[img.key]?.caption||img.name)}</p><div class="actions"><button class="small" onclick="editImage('${esc(img.key)}')">Annotate / measure</button><button class="small ghost" onclick="openImgModal('${esc(img.src)}')">View</button></div></div></article>`).join('')}</div>${images.length?'':'<p class="muted">No analysis images yet. Add the overview first, followed by close-up views of each cut.</p>'}<details class="archive-box"><summary>Optional reference folder or CAD model link</summary><p class="muted">Use a shared HTTPS link for a native CAD model or full-resolution archive.</p><div class="actions"><input id="archive-url" aria-label="Reference folder or CAD model URL" placeholder="https://…" value="${esc(r.archiveURL||'')}" style="flex:1;min-width:180px"><button onclick="saveArchive()">Save link</button>${XSCore.archiveURL(r.archiveURL)?`<a href="${esc(XSCore.archiveURL(r.archiveURL))}" target="_blank" rel="noopener noreferrer">Open reference</a>`:''}</div><div id="archive-status" role="status"></div></details></div>
  <div id="result-panel-measurements" class="results-panel" hidden><h3>Measurement log</h3><p class="muted" style="margin:8px 0 18px">Record microscope readings, or open an image to calibrate and measure a distance. Limits come from your specification.</p><div class="measure-form"><label>Feature / cut<input id="meas-feature" placeholder="TIM1 · cut A–A"></label><label>Value<input id="meas-value" type="number" step="any" placeholder="98.5"></label><label>Unit<select id="meas-unit"><option>µm</option><option>mm</option><option>nm</option><option>%</option><option>°</option></select></label><label>Lower limit<input id="meas-min" type="number" step="any" placeholder="Optional"></label><label>Upper limit<input id="meas-max" type="number" step="any" placeholder="Optional"></label></div><div class="actions" style="margin-top:14px"><button class="primary" onclick="addMeasurement()">Add measurement</button><button onclick="exportMeasurements()">Download CSV</button></div><div id="measurement-status" role="status"></div><div class="table-wrap"><table><thead><tr><th>Feature / cut</th><th>Value</th><th>Limits</th><th>Assessment</th><th>Source</th><th></th></tr></thead><tbody>${measurements.map(m=>`<tr><td>${esc(m.feature)}</td><td>${esc(Number(m.value).toFixed(3).replace(/\.?0+$/,''))} ${esc(m.unit)}</td><td>${esc(m.min??'—')} to ${esc(m.max??'—')}</td><td class="${XSCore.verdict(Number(m.value),m.min,m.max)==='Outside limits'?'measure-fail':'measure-pass'}">${esc(XSCore.verdict(Number(m.value),m.min,m.max))}</td><td>${esc(m.source||'Manual')}</td><td><button class="small ghost" aria-label="Remove measurement ${esc(m.feature)}" onclick="removeMeasurement('${esc(m.id)}')">Remove</button></td></tr>`).join('')||'<tr><td colspan="6" class="muted">No measurements recorded.</td></tr>'}</tbody></table></div><p class="storage-copy">Image measurements refer to the saved, optimized image. Calibrate against a scale bar in that same image. Use the microscope or metrology system for final acceptance.</p></div>
  <div id="result-panel-summary" class="results-panel" hidden><h3 class="report-heading">Summary & conclusion</h3><div class="result-summary"><div class="full"><label for="result-summary">Analysis summary</label><textarea id="result-summary" placeholder="What was sectioned? Which cuts and methods were used?">${esc(summary.summary||'')}</textarea></div><div><label for="result-conclusion">Conclusion</label><textarea id="result-conclusion" placeholder="What do the images and measurements establish? Separate observations from suspected causes.">${esc(summary.conclusion||'')}</textarea></div><div><label for="result-nextSteps">Recommended action / next steps</label><textarea id="result-nextSteps" placeholder="Follow-up action, owner, and any additional analysis needed.">${esc(summary.nextSteps||'')}</textarea></div><div><label for="result-disposition">Disposition</label><select id="result-disposition">${['Not assessed','Meets specification','Does not meet specification','Further analysis required'].map(s=>`<option ${summary.disposition===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="actions" style="margin-top:18px"><button class="primary" onclick="saveResults()">Save summary & conclusion</button><span class="muted" id="summary-status" role="status">${summary.updatedAt?'Last saved '+esc(fmtDate(summary.updatedAt)):''}</span></div></div>`;
  view.firstElementChild.after(target);selectResultTab(resultTab);addDropZone($('results-drop'),uploadResultImages);target.addEventListener('input',e=>{if(e.target.closest('#result-panel-summary')){resultsDirty=true;statusMessage('summary-status','Unsaved changes');}});
};
function selectResultTab(tab){resultTab=tab;for(const t of ['images','measurements','summary']){$('result-panel-'+t).hidden=t!==tab;$('result-tab-'+t).classList.toggle('active',t===tab);$('result-tab-'+t).setAttribute('aria-selected',String(t===tab));}}
async function uploadResultImages(files){
  if(uploadBusy||!files.length)return;if(files.length>12){statusMessage('result-upload-status','Add up to 12 pictures at a time. You can add another batch afterward.',true);return;}
  uploadBusy=true;const reqId=selectedReqId;try{const processed=[];for(let i=0;i<files.length;i++){statusMessage('result-upload-status',`Optimizing picture ${i+1} of ${files.length}…`);processed.push(await optimizeImage(files[i]));}const r=requests.find(r=>r.id===reqId),message={id:uid(),author:currentUser.id,authorName:currentUser.name,text:'X-section images',kind:'analysis',images:processed.map(p=>p.src),imageNames:processed.map(p=>p.name),measurements:[],ts:new Date().toISOString()};const candidate={...r,messages:[...r.messages,message]};XSectionStore.valid(candidate);requests=requests.map(r=>r.id===reqId?candidate:r);if(await saveData()){resultTab='images';renderDetail();showToast(`${processed.length} image(s) saved to the shared request.`);}}catch(e){statusMessage('result-upload-status',e.message,true);}finally{uploadBusy=false;}
}
async function saveArchive(){const value=$('archive-url').value.trim();if(value&&!XSCore.archiveURL(value)){statusMessage('archive-status','Enter a valid HTTPS URL.',true);return;}const r=rawRequest();r.archiveURL=value;if(await saveData()){renderDetail();showToast('Reference link saved.');}}
async function addMeasurement(){const feature=$('meas-feature').value.trim(),value=Number($('meas-value').value),min=$('meas-min').value,max=$('meas-max').value;const verdict=XSCore.verdict(value,min,max);if(!feature||$('meas-value').value===''||!Number.isFinite(value)||verdict.startsWith('Invalid')){statusMessage('measurement-status','Enter a feature and a numeric value. Lower limit must not exceed upper limit.',true);return;}const r=rawRequest(),id=uid();r.resultMeasurements={...r.resultMeasurements,[id]:{id,feature,value,unit:$('meas-unit').value,min:min===''?null:Number(min),max:max===''?null:Number(max),source:'Manual',createdAt:new Date().toISOString()}};if(await saveData()){resultTab='measurements';renderDetail();}}
async function removeMeasurement(id){const r=rawRequest();delete r.resultMeasurements[id];if(await saveData())renderDetail();}
async function saveResults(){const r=rawRequest();r.results={summary:$('result-summary').value.trim(),conclusion:$('result-conclusion').value.trim(),nextSteps:$('result-nextSteps').value.trim(),disposition:$('result-disposition').value,updatedAt:new Date().toISOString(),author:currentUser.name};if(await saveData()){resultsDirty=false;statusMessage('summary-status','Summary & conclusion saved.');showToast('Findings saved.');}}
function downloadFile(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportMeasurements(){const r=rawRequest(),rows=[['Feature','Value','Unit','Lower limit','Upper limit','Assessment','Source'],...Object.values(r.resultMeasurements||{}).map(m=>[m.feature,m.value,m.unit,m.min??'',m.max??'',XSCore.verdict(Number(m.value),m.min,m.max),m.source||'Manual'])];const cell=v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';downloadFile(r.id+'-measurements.csv',new Blob(['\ufeff'+rows.map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));}
function printReport(){if(resultsDirty){showToast('Save the summary before printing.');return;}window.print();}

// A per-image annotation editor. All coordinates are in saved image pixels.
let imageEditor=null;
async function editImage(key){
  const r=rawRequest(),asset=requestImages(r).find(a=>a.key===key);if(!asset)return;const image=await loadImage(asset.src),stored=structuredClone(r.imageAnnotations?.[key]||{});imageEditor={key,requestId:r.id,image,src:asset.src,caption:stored.caption||asset.name,marks:stored.marks||[],calibration:stored.calibration||null,mode:'measure',start:null,dirty:false};
  const overlay=document.createElement('div');overlay.id='image-editor';overlay.className='editor-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Annotate and measure image');overlay.innerHTML=`<div class="editor-shell"><div class="editor-head"><div><div class="eyebrow">Image workspace</div><h2>Mark what matters.</h2></div><div class="actions"><button onclick="downloadAnnotatedImage()">Download marked image</button><button class="primary" id="save-image-button" onclick="saveImageAnnotations()">Save annotations</button><button onclick="closeImageEditor()">Close</button></div></div><label for="image-caption" class="muted">Image caption / cut ID</label><input id="image-caption" value="${esc(imageEditor.caption)}" style="margin:8px 0 16px"><div class="editor-controls"><label>Tool<select id="image-tool" onchange="setImageTool(this.value)"><option value="measure">Measure distance</option><option value="calibrate">Calibrate scale bar</option><option value="arrow">Arrow</option><option value="rect">Region of interest</option><option value="text">Text label</option></select></label><label>Known distance<input id="calibration-value" type="number" min="0" step="any" placeholder="e.g. 100"></label><label>Unit<select id="calibration-unit"><option>µm</option><option>mm</option><option>nm</option></select></label><label>Label<input id="annotation-label" placeholder="Cut A–A / defect"></label><button onclick="undoImageMark()">Undo last mark</button><button onclick="clearCalibration()">Reset calibration</button></div><div id="editor-note" class="editor-note" role="status"></div><div class="editor-stage"><canvas id="analysis-canvas" width="${image.naturalWidth}" height="${image.naturalHeight}" tabindex="0" aria-label="Image annotation canvas. Click two points to mark a distance."></canvas></div><p class="muted" style="margin:14px 0">Click two points on the image. For real units, choose Calibrate scale bar, enter its known distance, and click both ends of the bar. Recalibrate each image independently.</p></div>`;document.body.append(overlay);$('image-caption').addEventListener('input',()=>imageEditor.dirty=true);$('analysis-canvas').addEventListener('pointerdown',imagePoint);setImageTool('measure');drawImageEditor();$('image-tool').focus();
}
function setImageTool(mode){imageEditor.mode=mode;imageEditor.start=null;statusMessage('editor-note',mode==='calibrate'?'Enter the scale bar’s known distance and unit, then click its two ends.':mode==='text'?'Enter a label, then click where to place it.':mode==='measure'?(imageEditor.calibration?'Calibrated. Click the two ends of the feature to measure.':'No calibration yet. Distances will be in pixels. Calibrate a known scale bar for real units.'):'Click two points to place the mark.');}
function imagePoint(e){const ed=imageEditor,cv=$('analysis-canvas'),rect=cv.getBoundingClientRect(),point={x:(e.clientX-rect.left)*cv.width/rect.width,y:(e.clientY-rect.top)*cv.height/rect.height};
  if(ed.mode==='text'){const text=$('annotation-label').value.trim();if(!text){statusMessage('editor-note','Enter a text label first.',true);return;}ed.marks.push({id:uid(),type:'text',a:point,text});ed.dirty=true;drawImageEditor();return;}
  if(!ed.start){ed.start=point;statusMessage('editor-note','First point set. Click the second point.');drawImageEditor();return;}const a=ed.start,b=point;ed.start=null;const pixels=Math.hypot(b.x-a.x,b.y-a.y);if(pixels<2){statusMessage('editor-note','Choose points farther apart.',true);return;}
  if(ed.mode==='calibrate'){const value=Number($('calibration-value').value);if(!(value>0&&Number.isFinite(value))){statusMessage('editor-note','Enter a positive known distance, then mark the scale bar again.',true);return;}ed.calibration={pixels,value,unit:$('calibration-unit').value,a,b};statusMessage('editor-note',`Scale set: ${value} ${ed.calibration.unit} = ${pixels.toFixed(1)} px. Switch to Measure distance.`);}else{ed.marks.push({id:uid(),type:ed.mode,a,b,text:$('annotation-label').value.trim()});const length=XSCore.length(a,b,ed.calibration);statusMessage('editor-note',ed.mode==='measure'?`${length.value.toFixed(3)} ${length.unit} · save annotations to add this to the measurement log.`:'Mark added.');}ed.dirty=true;drawImageEditor();
}
function drawImageEditor(ed=imageEditor,cv=$('analysis-canvas')){if(!ed||!cv)return;const ctx=cv.getContext('2d');ctx.clearRect(0,0,cv.width,cv.height);ctx.drawImage(ed.image,0,0);const lw=Math.max(2,cv.width/500),font=Math.max(16,cv.width/65);ctx.lineWidth=lw;ctx.font=`600 ${font}px Segoe UI`;ctx.textBaseline='top';
  const label=(text,x,y)=>{const w=ctx.measureText(text).width;ctx.fillStyle='#0a130cec';ctx.fillRect(Math.min(x,cv.width-w-12),Math.max(0,y),w+12,font+10);ctx.fillStyle='#d1ff9c';ctx.fillText(text,Math.min(x,cv.width-w-12)+6,Math.max(0,y)+4);};
  for(const mark of ed.marks){ctx.strokeStyle='#b3ff4c';ctx.fillStyle='#b3ff4c';if(mark.type==='text'){label(mark.text,mark.a.x,mark.a.y);continue;}const {a,b}=mark;ctx.beginPath();if(mark.type==='rect')ctx.rect(a.x,a.y,b.x-a.x,b.y-a.y);else{ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);}ctx.stroke();if(mark.type==='arrow'){const angle=Math.atan2(b.y-a.y,b.x-a.x),size=font;ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-size*Math.cos(angle-.45),b.y-size*Math.sin(angle-.45));ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-size*Math.cos(angle+.45),b.y-size*Math.sin(angle+.45));ctx.stroke();}if(mark.type==='measure'){const l=XSCore.length(a,b,ed.calibration);label((mark.text?mark.text+' · ':'')+l.value.toFixed(3)+' '+l.unit,(a.x+b.x)/2,(a.y+b.y)/2);}else if(mark.text)label(mark.text,a.x,a.y);}
  if(ed.calibration){ctx.strokeStyle='#48dfff';ctx.beginPath();ctx.moveTo(ed.calibration.a.x,ed.calibration.a.y);ctx.lineTo(ed.calibration.b.x,ed.calibration.b.y);ctx.stroke();}if(ed.start){ctx.fillStyle='#ffce5a';ctx.beginPath();ctx.arc(ed.start.x,ed.start.y,lw*3,0,Math.PI*2);ctx.fill();}
}
function undoImageMark(){if(imageEditor.start)imageEditor.start=null;else imageEditor.marks.pop();imageEditor.dirty=true;drawImageEditor();}
function clearCalibration(){imageEditor.calibration=null;imageEditor.dirty=true;drawImageEditor();statusMessage('editor-note','Calibration removed. Measurements will be saved in pixels.');}
async function saveImageAnnotations(){const ed=imageEditor,r=requests.find(r=>r.id===ed.requestId);$('save-image-button').disabled=true;try{const caption=$('image-caption').value.trim();r.imageAnnotations={...r.imageAnnotations,[ed.key]:{caption,marks:ed.marks,calibration:ed.calibration}};const measurements={...r.resultMeasurements};for(const [id,m]of Object.entries(measurements))if(m.imageKey===ed.key)delete measurements[id];for(const mark of ed.marks.filter(m=>m.type==='measure')){const l=XSCore.length(mark.a,mark.b,ed.calibration);measurements[mark.id]={id:mark.id,feature:mark.text||caption||'Image distance',value:l.value,unit:l.unit,min:null,max:null,source:caption||'Image',imageKey:ed.key};}r.resultMeasurements=measurements;if(await saveData()){ed.dirty=false;resultsDirty=false;renderDetail();statusMessage('editor-note','Annotations and measurements saved.');}}catch(e){statusMessage('editor-note',e.message,true);}finally{if($('save-image-button'))$('save-image-button').disabled=false;}}
function closeImageEditor(){if(imageEditor?.dirty&&!confirm('Close without saving these annotations?'))return;$('image-editor')?.remove();imageEditor=null;}
function downloadAnnotatedImage(){const cv=$('analysis-canvas');cv.toBlob(blob=>downloadFile(imageEditor.requestId+'-annotated.png',blob),'image/png');}

// Guard work in progress against background refreshes and accidental navigation.
const originalIsTyping=isTyping;isTyping=function(){return originalIsTyping()||resultsDirty||!!imageEditor||uploadBusy;};
const originalShowView=showView;showView=function(v){if(uploadBusy){showToast('Wait for the image upload to finish.');return;}if(resultsDirty&&v!==currentView){if(!confirm('Leave without saving the summary?'))return;resultsDirty=false;}if(currentView==='new'&&v!=='new'&&formDirty){clearTimeout(draftTimer);draftOp('put',captureDraft()).catch(()=>{});}originalShowView(v);window.scrollTo({top:0,behavior:'instant'});};
window.addEventListener('beforeunload',e=>{if(formDirty||resultsDirty||imageEditor?.dirty||uploadBusy){e.preventDefault();e.returnValue='';}});
document.addEventListener('paste',e=>{const file=[...(e.clipboardData?.items||[])].find(i=>i.type.startsWith('image/'))?.getAsFile();if(!file||imageEditor)return;if(currentView==='new'&&wizardStep===1){e.preventDefault();useDrawingFile(file);}else if(currentView==='detail'&&resultTab==='images'){e.preventDefault();uploadResultImages([file]);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&imageEditor)closeImageEditor();});
// Replace unbounded legacy reply image reads with the same validated image optimization.
handleImgUpload=async function(event){if(uploadBusy)return;uploadBusy=true;try{const files=[...event.target.files];if(pendingImages.length+files.length>12)throw Error('Attach at most 12 pictures per update.');for(const file of files){const image=await optimizeImage(file);pendingImages.push(image.src);}const preview=$('img-preview-row');preview.querySelectorAll('.img-thumb').forEach(el=>el.remove());pendingImages.forEach((src,i)=>{const thumb=document.createElement('div');thumb.className='img-thumb';const img=document.createElement('img');img.src=src;img.alt='Pending image '+(i+1);const button=document.createElement('button');button.textContent='×';button.setAttribute('aria-label','Remove pending image');button.onclick=()=>{pendingImages[i]=null;thumb.remove();};thumb.append(img,button);preview.prepend(thumb);});}catch(e){connectionError(e.message);}finally{uploadBusy=false;event.target.value='';}};
const originalSendReply=sendReply;sendReply=async function(id){if(uploadBusy)return;pendingImages=pendingImages.filter(Boolean);await originalSendReply(id);};
// Draw controls must never consume Backspace or browser zoom shortcuts while typing.
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')&&['Backspace','Delete','Equal','Minus','Digit0'].includes(e.code))e.stopImmediatePropagation();},true);
// Prefer dedicated file storage for originals; retain a working embedded-image mode
// when the project's bucket has not yet been enabled by its administrator.
uploadResultImages=async function(files){
  if(resultsDirty){showToast('Save your summary before adding images.');return;}if(uploadBusy||!files.length)return;if(files.length>12){statusMessage('result-upload-status','Add up to 12 images per batch.',true);return;}uploadBusy=true;const reqId=selectedReqId;
  try{const processed=[],metadata=[];let embedded=0;
    for(let i=0;i<files.length;i++){
      statusMessage('result-upload-status',`Preparing image ${i+1} of ${files.length}…`);const file=files[i],view=await optimizeImage(file);let src=view.src,meta={name:view.name,mode:'embedded',originalBytes:view.originalBytes};
      if(!XSFiles.isUnavailable())try{
        const original=await XSFiles.upload(reqId,file,file.name,p=>statusMessage('result-upload-status',`Saving original ${i+1} of ${files.length}: ${p}%`));
        const blob=await (await fetch(view.src)).blob(),preview=await XSFiles.upload(reqId,blob,'view.jpg');src=preview.url;meta={...meta,mode:'cloud',originalURL:original.url,originalPath:original.path,previewPath:preview.path};
      }catch{embedded++;}else embedded++;
      processed.push({src,name:view.name});metadata.push(meta);
    }
    const r=requests.find(r=>r.id===reqId),message={id:uid(),author:currentUser.id,authorName:currentUser.name,text:embedded?'X-section images · optimized copies saved; originals not stored.':'X-section images · originals preserved in file storage.',kind:'analysis',images:processed.map(p=>p.src),imageNames:processed.map(p=>p.name),imageMeta:metadata,measurements:[],ts:new Date().toISOString()};
    const candidate={...r,messages:[...r.messages,message]};XSectionStore.valid(candidate);requests=requests.map(r=>r.id===reqId?candidate:r);if(await saveData()){resultTab='images';renderDetail();statusMessage('result-upload-status',embedded?`${processed.length} optimized image(s) saved. Full-resolution storage is not connected; originals remain on your device.`:`${processed.length} image(s) and their full-resolution originals saved.`);showToast('Images saved to the request.');}
  }catch(e){statusMessage('result-upload-status',e.message+' Your source files are unchanged.',true);}finally{uploadBusy=false;}
};
const basicStorageMarkup=storageMarkup;
storageMarkup=function(r){const cloud=(r.messages||[]).flatMap(m=>m.imageMeta||[]).filter(m=>m.mode==='cloud'),embedded=(r.messages||[]).flatMap(m=>m.images||[]).filter(src=>src.startsWith('data:')).length;return basicStorageMarkup(r)+`<p class="storage-copy" style="margin-top:8px">${cloud.length} full-resolution original(s) in file storage · ${embedded} embedded optimized image(s). <a href="storage-setup.html" target="_blank" rel="noopener noreferrer">Full-resolution storage setup</a></p>`;};
const detailWithResults=renderDetail;
renderDetail=function(){detailWithResults();const r=rawRequest();if(!r)return;const images=requestImages(r);document.querySelectorAll('.image-card').forEach((card,i)=>{const asset=images[i],original=asset?.originalURL;if(original&&XSCore.cloudURL(original)){const a=document.createElement('a');a.href=original;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Download original';a.style.fontSize='.875rem';card.lastElementChild.append(a);}const remove=document.createElement('button');remove.className='small ghost';remove.textContent='Remove';remove.onclick=()=>removeResultImage(asset.key);card.querySelector('.actions').append(remove);if(r.imageAnnotations?.[asset.key]?.marks?.length)markedImage(asset,r).then(src=>{if(card.isConnected&&selectedReqId===r.id){card.querySelector('img').src=src;card.querySelector('.actions button:nth-child(2)').onclick=()=>openImgModal(src);}}).catch(()=>{});});
  const area=$('result-panel-images');if(area){const attachment=document.createElement('section');attachment.className='archive-box';attachment.innerHTML=`<h3>CAD models & reference files</h3><p class="muted" style="margin:8px 0">Attach a native model or reference PDF. To mark a cut on it, upload a screenshot in the cut plan.</p><button onclick="$('reference-upload').click()">Attach CAD / PDF file</button><input type="file" id="reference-upload" accept=".pdf,.step,.stp,.stl,.obj,.iges,.igs,.glb,.gltf" hidden onchange="uploadReferenceFile(this.files[0])"><div id="reference-status" role="status" class="upload-status"></div><div>${Object.values(r.referenceFiles||{}).filter(f=>XSCore.cloudURL(f.url)).map(f=>`<p><a href="${esc(f.url)}" target="_blank" rel="noopener noreferrer">${esc(f.name)}</a> <span class="muted">${humanBytes(f.bytes)}</span></p>`).join('')}</div>`;area.append(attachment);}
};
async function uploadReferenceFile(file){if(!file||uploadBusy)return;if(!/\.(pdf|step|stp|stl|obj|iges|igs|glb|gltf)$/i.test(file.name)){statusMessage('reference-status','Choose a PDF or supported CAD model.',true);return;}uploadBusy=true;try{const id=uid(),r=rawRequest(),asset=await XSFiles.upload(r.id,file,file.name,p=>statusMessage('reference-status',`Uploading ${p}%…`));r.referenceFiles={...r.referenceFiles,[id]:{id,...asset}};if(await saveData())renderDetail();}catch{statusMessage('reference-status','Full-resolution file storage must be enabled to attach CAD/PDF files. Open Full-resolution storage setup above.',true);}finally{uploadBusy=false;}}
async function removeResultImage(key){if(resultsDirty){showToast('Save the summary before removing an image.');return;}if(!confirm('Remove this image and its image measurements from the request? Any original in file storage is retained for owner recovery.'))return;const r=rawRequest(),candidate=structuredClone(r);for(const m of candidate.messages){const index=m.images.findIndex((_,i)=>m.id+'_'+i===key);if(index<0)continue;const annotations={...candidate.imageAnnotations},measurements={...candidate.resultMeasurements};for(const [id,measurement]of Object.entries(measurements)){if(measurement.imageKey===key)delete measurements[id];}delete annotations[key];for(let i=index+1;i<m.images.length;i++){const old=m.id+'_'+i,next=m.id+'_'+(i-1);if(annotations[old]){annotations[next]=annotations[old];delete annotations[old];}for(const measurement of Object.values(measurements))if(measurement.imageKey===old)measurement.imageKey=next;}m.images.splice(index,1);m.imageNames?.splice(index,1);m.imageMeta?.splice(index,1);candidate.imageAnnotations=annotations;candidate.resultMeasurements=measurements;break;}requests=requests.map(row=>row.id===r.id?candidate:row);if(await saveData())renderDetail();}

// Printable reports and PowerPoint share the saved annotations and explicit conclusion.
async function markedImage(asset,r){const image=await loadImage(asset.src),cv=document.createElement('canvas');cv.width=image.naturalWidth;cv.height=image.naturalHeight;const marks=r.imageAnnotations?.[asset.key]||{};drawImageEditor({image,marks:marks.marks||[],calibration:marks.calibration||null,start:null},cv);return cv.toDataURL('image/jpeg',.9);}
async function preparePresentationRequest(source){
  const r=structuredClone(source),assets=requestImages(r);for(const m of r.messages)for(let i=0;i<(m.images||[]).length;i++){const a=assets.find(a=>a.key===m.id+'_'+i);if(a)m.images[i]=await markedImage(a,source);}
  const s=r.results;if(s||Object.keys(r.resultMeasurements||{}).length)r.messages.push({id:'report_summary',author:currentUser.id,authorName:s?.author||currentUser.name,ts:s?.updatedAt||new Date().toISOString(),text:[s?.summary,s?.conclusion&&'Conclusion: '+s.conclusion,s?.disposition&&'Disposition: '+s.disposition,s?.nextSteps&&'Next steps: '+s.nextSteps].filter(Boolean).join('\n\n'),images:[],measurements:Object.values(r.resultMeasurements||{}).map(m=>`${m.feature}: ${Number(m.value).toFixed(3)} ${m.unit} (${XSCore.verdict(m.value,m.min,m.max)})`)});return r;
}
printReport=async function(){
  if(resultsDirty){showToast('Save the summary before printing.');return;}const r=rawRequest(),s=r.results||{},measurements=Object.values(r.resultMeasurements||{});let report=$('print-report');if(report)report.remove();report=document.createElement('article');report.id='print-report';report.innerHTML=`<h1>X-section analysis report</h1><p>${esc(r.id)} · ${esc(r.sampleId)} · ${esc(r.product)}</p><p>Requester: ${esc(r.requesterName||userName(r.requester))} · ${esc(fmtDay(r.created))} · ${esc(STATUS_CFG[r.status]?.label)}</p><h2>Cut plan</h2><p>${esc(r.cutLocation)} · ${esc(r.cutPlane)} · ${r.numCuts} cut(s)</p>${r.canvasDrawing?`<img src="${esc(r.canvasDrawing)}" alt="Cut plan" style="max-width:100%;max-height:350px">`:''}<h2>Summary</h2><p class="report-text">${esc(s.summary||'Not recorded')}</p><h2>Conclusion</h2><p class="report-text">${esc(s.conclusion||'Not recorded')}</p><p><strong>Disposition:</strong> ${esc(s.disposition||'Not assessed')}</p><h2>Next steps</h2><p class="report-text">${esc(s.nextSteps||'Not recorded')}</p><h2>Measurements</h2><table><thead><tr><th>Feature</th><th>Value</th><th>Limits</th><th>Assessment</th></tr></thead><tbody>${measurements.map(m=>`<tr><td>${esc(m.feature)}</td><td>${Number(m.value).toFixed(3)} ${esc(m.unit)}</td><td>${esc(m.min??'—')} to ${esc(m.max??'—')}</td><td>${esc(XSCore.verdict(m.value,m.min,m.max))}</td></tr>`).join('')}</tbody></table><h2>Images and annotations</h2>`;document.body.append(report);
  try{for(const asset of requestImages(r)){const figure=document.createElement('figure'),img=document.createElement('img'),caption=document.createElement('figcaption');img.src=await markedImage(asset,r);img.alt=r.imageAnnotations?.[asset.key]?.caption||asset.name;caption.textContent=img.alt;figure.append(img,caption);report.append(figure);await img.decode();}window.print();}catch(e){showToast('Report image could not be loaded: '+e.message);}
};
const guardedImageEditor=editImage;editImage=async function(key){if(resultsDirty){showToast('Save your summary before editing images.');return;}try{await guardedImageEditor(key);}catch(e){connectionError('Could not open this image: '+e.message);}};
const guardedStatus=updateStatus;updateStatus=async function(status,id){if(resultsDirty){showToast('Save your summary before changing status.');return;}return guardedStatus(status,id);};
const draftCanvasMD=canvasMD;canvasMD=function(e){const count=canvasShapes.length;draftCanvasMD(e);if(currentView==='new'&&count!==canvasShapes.length){formDirty=true;scheduleDraft();}};
const draftCanvasMU=canvasMU;canvasMU=function(e){const changed=canvasDrawing;draftCanvasMU(e);if(currentView==='new'&&changed){formDirty=true;scheduleDraft();}};
for(const name of ['canvasUndo','canvasClear','canvasDeleteSelected','editSelected','applyDimLabel']){const original=window[name];window[name]=function(...args){const result=original(...args);if(currentView==='new'){formDirty=true;scheduleDraft();}return result;};}
const utility=$('display-name').parentElement;utility.className='utility-bar';utility.innerHTML='<a href="https://yousefmahajna.github.io/interconnect-process-lab/">Process Lab</a><label for="display-name">Request as</label><input id="display-name" maxlength="80" style="width:200px" onchange="setDisplayName(this.value)"><details class="utility-menu"><summary>Connection & backup</summary><div class="actions"><button class="small" onclick="downloadBackup()">Download backup</button><button class="small" onclick="retryShared()">Retry connection / save</button><a href="shared-setup.html">Shared setup</a><a href="storage-setup.html">File storage setup</a></div></details>';
// The existing app boots after this enhancement layer is loaded.
startXSection();
